import Link from 'next/link';
import type { ReactNode } from 'react';
import { SITE_URL } from '../lib/seo';
import { readJevbenchComparisonLinks } from '../lib/jevbench-seo.mjs';
import { JevBoardGuides } from './JevBoardGuides';
import { jevMethodView } from '../lib/jev-decision-limit.mjs';

type Faq = { question: string; answer: string };
type Artifact = {
  revision: string;
  generated_utc: string;
  protocol: string;
  score_one_liner: string;
};
export type StructuredListItem = { name: string; url?: string | null };

export type SeoRow = {
  key: string;
  display: string;
  rank: number | null;
  ranked?: boolean;
  board?: 'open' | 'api' | 'reference' | string;
  capability?: number | null;
  capability_eligible?: boolean;
  last_measured_on?: string | null;
  measurement_revision?: string;
  jevbench_score: number | null;
  sealed_accuracy: number | null;
  public_accuracy?: number | null;
  public_minus_sealed_gap_pp?: number | null;
  axes: { intelligence: number | null; calibration: number | null; speed: number | null; cost: number | null };
  cost?: { kind?: string; usd_per_1000?: number | null; basis?: string }; 
  speed?: { p50_s_raw?: number | null; p50_s_adjusted?: number | null; p95_s_adjusted?: number | null; adjustment?: string | null };
  endpoint_condition?: string | null;
  open?: string | boolean | null;
  licence?: string | null;
  repo?: string | null;
};

// Review 6 Oct 2026: /jev-models ranks open weights only. `rank` is that board's rank; the Jev 1.13.0 reference and hosted API rows have none.
export function boardRankText(row: Pick<SeoRow, 'rank' | 'board' | 'ranked'>, locale: 'en' | 'de' = 'en'): string {
  const de = locale === 'de';
  if (row.board === 'reference') return de ? 'Referenz, nicht gerankt' : 'Reference, not ranked';
  if (row.board === 'api' && row.ranked === false) return de ? 'API-Angebot, gelistet, nicht gerankt' : 'API offering, listed but not ranked';
  if (row.board === 'api') return de ? 'API-Angebot, gerankt auf dem API-Leaderboard' : 'API offering, ranked on the API leaderboard';
  if (row.rank == null) return de ? 'Ohne Rang (außerhalb der Grenzen)' : 'Outside the caps, no rank';
  return de ? `Rang ${row.rank} (Open-Weights-Board)` : `Rank #${row.rank} (open-weights board)`;
}

export function ApiBoardNote({ rows, locale = 'en' }: { rows: Array<Pick<SeoRow, 'key' | 'display'>>; locale?: 'en' | 'de' }) {
  const de = locale === 'de';
  const names = rows.map((r) => r.display.split(' (')[0]).join(', ');
  return <p className="bh-muted mt-3 text-sm" data-bh-jev-api-board-note>{de ? 'API-Angebote werden auf dem API-Leaderboard gerankt' : 'Hosted API alternatives are ranked on the API leaderboard'}{names && ` (${names})`}: <Link className="text-accent underline" href="/jev-models/api">{de ? 'zum API-Leaderboard' : 'JevBench API leaderboard'}</Link>.</p>;
}

export function one(value: number | null | undefined): string {
  return value == null || !Number.isFinite(value) ? '—' : value.toFixed(1);
}

export function percent(value: number | null | undefined): string {
  return value == null || !Number.isFinite(value) ? '—' : `${(value * 100).toFixed(1)}%`;
}

export function usdPerThousand(value: number | null | undefined): string {
  if (value == null || !Number.isFinite(value)) return 'not published';
  return `$${value.toFixed(value < 0.01 ? 4 : 3)} per 1,000 decisions`;
}

export function costBasisLabel(kind: string | null | undefined): string {
  if (kind === 'tariff') return 'public list price';
  if (kind === 'measured') return 'measured';
  if (kind === 'estimate') return 'estimated';
  if (kind === 'announced') return 'self-reported announced price';
  return 'not published';
}

export function opennessLabel(row: SeoRow): string {
  if (row.open === 'yes' || row.open === true) return 'Code and weights marked open in the published row';
  if ((row.open === 'weights' || row.open === 'open weights')) return 'Weights marked open in the published row';
  if (row.open === 'no') return 'Marked closed in the published row';
  return 'Unknown in the published row';
}

export function DatasetFaqJsonLd({ path, artifact, faq, items, itemListName, variables, breadcrumbName, de }: {
  path: string;
  artifact: Artifact;
  faq: Faq[];
  items?: StructuredListItem[];
  itemListName?: string;
  variables?: string[];
  breadcrumbName?: string;
  de?: { datasetName: string; datasetDescription: string };
}) {
  const canonical = new URL(path, SITE_URL).toString();
  const json = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Dataset',
        '@id': `${canonical}#dataset`,
        name: de?.datasetName ?? `JevBench ${artifact.revision} public aggregate — Benchmark Heaven`,
        description: de?.datasetDescription ?? 'Published aggregate benchmark results for Jev-class decision models, with separate intelligence, calibration, speed and cost measures.',
        ...(de ? { inLanguage: 'de' } : {}),
        url: canonical,
        creator: { '@type': 'Organization', name: 'Benchmark Heaven', url: SITE_URL },
        isAccessibleForFree: true,
        dateModified: artifact.generated_utc,
        version: artifact.revision,
        measurementTechnique: artifact.score_one_liner,
        variableMeasured: variables ?? ['JevBench Score', 'Intelligence', 'Calibration', 'Speed', 'Cost', 'sealed accuracy'],
        distribution: {
          '@type': 'DataDownload',
          encodingFormat: 'application/json',
          contentUrl: `${SITE_URL}/api/jevbench/${artifact.revision}`,
        },
        // F-212 (pass 40): the dataset record names the release it describes; the method doc is tagged with every release.
        citation: `https://github.com/fstandhartinger/jevbench/blob/${artifact.revision}/docs/METHOD-v1.4.md`,
      },
      // Only for a list the page shows in full, in the same order.
      ...(items?.length ? [{
        '@type': 'ItemList',
        '@id': `${canonical}#item-list`,
        name: itemListName ?? `Systems in JevBench ${artifact.revision}`,
        itemListOrder: 'https://schema.org/ItemListOrderAscending',
        numberOfItems: items.length,
        itemListElement: items.map(({ name, url }, index) => ({
          '@type': 'ListItem',
          position: index + 1,
          item: { '@type': 'Thing', name, ...(url ? { url } : {}) },
        })),
      }] : []),
      breadcrumbJsonLd(path, breadcrumbName ?? path.split('/').pop()?.replace(/-/g, ' ') ?? 'JevBench'),
      {
        '@type': 'FAQPage',
        ...(de ? { inLanguage: 'de' } : {}),
        '@id': `${canonical}#faq`,
        mainEntity: faq.map(({ question, answer }) => ({
          '@type': 'Question',
          name: question,
          acceptedAnswer: { '@type': 'Answer', text: answer },
        })),
      },
    ],
  };
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(json).replace(/</g, '\\u003c') }} />;
}

export function JevFaq({ items, heading = 'Frequently asked questions' }: { items: Faq[]; heading?: string }) {
  return (
    <section className="bh-panel mt-8 p-5" aria-labelledby="jev-intent-faq">
      <h2 id="jev-intent-faq" className="text-xl font-semibold">{heading}</h2>
      <dl className="mt-3 space-y-4">
        {items.map(({ question, answer }) => (
          <div key={question}>
            <dt className="font-semibold">{question}</dt>
            <dd className="bh-muted mt-1">{answer}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

const JEV_GUIDES = [
  { key: 'alternatives', href: '/jev-models/alternatives', label: 'Jev-compatible model alternatives' },
  { key: 'chooser', href: '/jev-models/how-to-choose', label: 'How to choose a Jev-compatible model' },
  { key: 'openSource', href: '/jev-models/open-source-jev', label: 'Is Jev open source?' },
] as const;

export function JevIntentLinks({ current }: { current: 'alternatives' | 'chooser' | 'openSource' }) {
  const sibling = current === 'alternatives'
    ? { href: '/jev-models/how-to-choose', label: 'How to choose a Jev-compatible model' }
    : { href: '/jev-models/alternatives', label: 'Jev-compatible model alternatives' };
  const others = JEV_GUIDES.filter((guide) => guide.key !== current && guide.href !== sibling.href);
  return (
    <nav className="mt-5 flex flex-wrap gap-x-4 gap-y-2 text-sm" aria-label="JevBench guides" data-bh-jev-guides={current}>
      <Link className="text-accent underline" href="/jev-models">Live JevBench board</Link>
      <Link className="text-accent underline" href={sibling.href}>{sibling.label}</Link>
      {others.map((guide) => <Link className="text-accent underline" href={guide.href} key={guide.href}>{guide.label}</Link>)}
      <Link className="text-accent underline" href="/jev-models/methodology">JevBench methodology</Link>
      <a className="text-accent underline" href="https://github.com/fstandhartinger/jevbench">JevBench method and repository</a>
    </nav>
  );
}

export async function JevBoardIntentLinks() {
  const comparisons = await readJevbenchComparisonLinks();
  return <JevBoardGuides links={[
    { href: '/jev-models/alternatives', label: 'Compare Jev-compatible alternatives' },
    { href: '/jev-models/how-to-choose', label: 'Choose a Jev-compatible model by use case' },
    { href: '/jev-models/open-source-jev', label: 'Is Jev open source? Open-weight options' },
    ...comparisons.map((pair) => ({ href: `/jev-models/${pair.slug}`, label: `Jev vs ${pair.label}` })),
  ]} />;
}

export function JevRowLink({ row, children }: { row: SeoRow; children?: ReactNode }) {
  return <Link className="text-accent underline" href={`/jev-models/${encodeURIComponent(row.key)}`}>{children ?? row.display}</Link>;
}

export function breadcrumbJsonLd(path: string, name: string) {
  return { '@type': 'BreadcrumbList', itemListElement: [
    { '@type': 'ListItem', position: 1, name: 'Benchmark Heaven', item: SITE_URL },
    { '@type': 'ListItem', position: 2, name: 'JevBench', item: `${SITE_URL}/jev-models` },
    { '@type': 'ListItem', position: 3, name, item: `${SITE_URL}${path}` },
  ] };
}
type StampRow = { key?: string; listing?: string; method?: string | null; rescored_in?: string | null; new_in?: string | null; remeasured_in?: string | null };
/** Release line of a page. With `row` (model pages) the method note follows the row: re-scored, measured under the rule, or re-measure pending with its v1.6 values. */
export function JevReleaseStamp({ data, row }: { data: { artifact: {revision: string}; date: string; releasePage: string; feed?: { method?: { label?: string } | null } }; row?: StampRow }) {
  const view = row ? jevMethodView(row) : null;
  const note = !data.feed?.method ? null
    : !row ? 'method v1.7 (10 s rule), re-scored from the recorded per-decision times'
    : view?.kind === 'v1.6-pending' ? 're-measure pending under the 10 s rule (v1.6 values)'
    : view?.kind !== 'v1.7' ? null
    : row.new_in || row.remeasured_in ? 'method v1.7 (10 s rule), measured under the rule'
    : 'method v1.7 (10 s rule), re-scored from the recorded per-decision times';
  return <p className="bh-muted mt-2 text-sm">Data: JevBench {data.artifact.revision}, published <Link className="text-accent underline" href={data.releasePage}>{data.date.slice(0,10)}</Link>{note && <> · <span data-bh-jev-method-stamp>{note}</span></>}</p>;
}

